(()=>{
'use strict';if(window.__gtavAdminPushLoaded)return;window.__gtavAdminPushLoaded=true;
const API='/api/push',TOKEN_KEY='gtav-admin-token-v2';
const $=id=>document.getElementById(id);let panel,tab,statusNode,subscriberNode,historyNode;
function headers(){return{'Content-Type':'application/json','X-Admin-Token':sessionStorage.getItem(TOKEN_KEY)||'','Accept':'application/json'}}
async function req(url,options={}){const r=await fetch(url,{cache:'no-store',...options});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'request_failed');return d}
function when(v){if(!v)return'—';const d=new Date(String(v).replace(' ','T')+'Z');return Number.isNaN(d.getTime())?v:new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)}
function status(text,kind=''){statusNode.textContent=text;statusNode.className='form-status'+(kind?' '+kind:'')}
function activate(){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x===panel));load()}
async function load(){
 const token=sessionStorage.getItem(TOKEN_KEY);if(!token){status('Unlock the dashboard first.','error');return}
 try{const data=await req(API+'?mode=admin',{headers:headers()});subscriberNode.textContent=String(data.subscribers||0);renderHistory(data.history||[]);status('Ready.')}catch(e){status(e.message==='unauthorized'?'Admin session is locked.':'Notification API unavailable.','error')}
}
function renderHistory(rows){historyNode.replaceChildren();if(!rows.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='No notifications sent yet.';historyNode.append(empty);return}rows.forEach(row=>{const card=document.createElement('article');card.className='release-item';const top=document.createElement('div');top.className='release-top';const pill=document.createElement('span');pill.className='pill';pill.textContent='PUSH';const time=document.createElement('time');time.textContent=when(row.created_at);top.append(pill,time);const h=document.createElement('h3');h.textContent='GTA V IOS Website';const p=document.createElement('p');p.textContent=row.body;const meta=document.createElement('p');meta.textContent=`Sent ${row.sent_count||0} · Failed ${row.failed_count||0} · ${row.target_url||'/updates.html'}`;card.append(top,h,p,meta);historyNode.append(card)})}
async function send(e){
 e.preventDefault();const button=$('push-send'),body=$('push-body').value.trim(),url=$('push-url').value.trim()||'/updates.html';if(!body){status('Write a notification message first.','error');return}
 button.disabled=true;status('Sending notification…');try{const data=await req(API,{method:'POST',headers:headers(),body:JSON.stringify({action:'send',body,url})});status(`Sent to ${data.sent||0} subscriber(s). ${data.failed||0} failed.`,'ok');$('push-body').value='';await load()}catch(error){status('Could not send: '+error.message,'error')}finally{button.disabled=false}
}
function build(){
 const tabs=document.querySelector('.tabs'),releases=document.querySelector('#panel-releases');if(!tabs||!releases)return;
 tab=document.createElement('button');tab.className='tab';tab.type='button';tab.textContent='Notifications';tab.addEventListener('click',activate);tabs.append(tab);
 panel=document.createElement('section');panel.className='panel';panel.id='panel-notifications';panel.innerHTML=`<div class="push-admin-grid"><section class="card"><div class="card-head"><div><h2>Send notification</h2><small>Title is fixed as “GTA V IOS Website”</small></div><span class="pill"><span id="push-subscribers">0</span>&nbsp;SUBSCRIBERS</span></div><div class="push-admin-preview"><img src="/assets/notification-logo.jpeg" alt=""><div><strong>GTA V IOS Website</strong><span id="push-preview-body">Your notification message will appear here.</span></div></div><form id="push-form" class="form-grid"><div class="field"><label for="push-body">Message *</label><textarea id="push-body" maxlength="240" placeholder="A new GTA V iOS update is now available." required></textarea></div><div class="field"><label for="push-url">Open this page when tapped</label><input id="push-url" value="/updates.html" placeholder="/updates.html"></div><div class="toolbar-group"><button class="button compact" id="push-send" type="submit">Send to all subscribers</button><button class="button outline compact" id="push-refresh" type="button">Refresh</button><span id="push-status" class="form-status"></span></div></form></section><aside class="card"><div class="card-head"><div><h2>Notification history</h2><small>Newest first</small></div></div><div class="release-list" id="push-history"></div></aside></div>`;
 releases.after(panel);subscriberNode=$('push-subscribers');historyNode=$('push-history');statusNode=$('push-status');$('push-form').addEventListener('submit',send);$('push-refresh').addEventListener('click',load);$('push-body').addEventListener('input',e=>{$('push-preview-body').textContent=e.target.value||'Your notification message will appear here.'});
 const style=document.createElement('style');style.textContent='.push-admin-grid{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(320px,.95fr);gap:14px}.push-admin-preview{display:flex;align-items:center;gap:12px;border:1px solid color-mix(in srgb,currentColor 10%,transparent);border-radius:16px;padding:14px;margin-bottom:16px}.push-admin-preview img{width:56px;height:56px;border-radius:12px;object-fit:cover;background:#000}.push-admin-preview div{display:grid;gap:5px}.push-admin-preview strong{font-size:.86rem}.push-admin-preview span{font-size:.72rem;color:var(--muted,#999);line-height:1.45}@media(max-width:860px){.push-admin-grid{grid-template-columns:1fr}}';document.head.append(style);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',build);else build();
})();